const fail = async (run: () => any): Promise<string> => {
  try {
    await run();
    return "ok";
  } catch (e: any) {
    return e.name + ": " + e.message;
  }
};
const hex = (b: ArrayBuffer): string => Buffer.from(b).toString("hex");
async function main(): Promise<void> {
  const enc = new TextEncoder();
  const base = await crypto.subtle.importKey("raw", enc.encode("pencil"), "PBKDF2", false, ["deriveBits", "deriveKey"]);
  const salt = Buffer.from("QSXCR+Q6sek8bf92", "base64");
  const salted = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: salt, iterations: 4096 }, base, 256);
  console.log(hex(salted));
  const hmac = await crypto.subtle.importKey("raw", salted, { name: "HMAC", hash: { name: "SHA-256" } }, false, ["sign"]);
  const clientKey = await crypto.subtle.sign("HMAC", hmac, enc.encode("Client Key"));
  console.log(hex(await crypto.subtle.digest("SHA-256", clientKey)));
  const aes = await crypto.subtle.deriveKey({ name: "PBKDF2", hash: "SHA-1", salt: new Uint8Array(0), iterations: 2 }, base, { name: "AES-GCM", length: 128 }, true, ["encrypt"]);
  console.log(aes.algorithm.name, aes.usages.join(","), hex(await crypto.subtle.exportKey("raw", aes)));
  console.log(await fail(() => crypto.subtle.importKey("raw", enc.encode("pw"), "PBKDF2", true, ["deriveBits"])));
  console.log(await fail(() => crypto.subtle.importKey("raw", enc.encode("pw"), "PBKDF2", false, ["sign"])));
  console.log(await fail(() => crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: salt, iterations: 0 }, base, 256)));
  console.log(await fail(() => crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: salt, iterations: 1 }, base, 7)));
  console.log(await fail(() => crypto.subtle.deriveBits({ name: "PBKDF2", hash: "MD5", salt: salt, iterations: 1 }, base, 128)));
  console.log(await fail(() => crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: salt, iterations: 1 }, hmac, 128)));
  console.log(await fail(() => crypto.subtle.deriveKey({ name: "PBKDF2", hash: "SHA-256", salt: salt, iterations: 1 }, base, { name: "HMAC", hash: "SHA-256", length: 0 }, true, ["sign"])));
  console.log(await fail(() => crypto.subtle.exportKey("raw", base)));
  console.log(base.type, base.extractable, base.usages.join(","), JSON.stringify(base.algorithm));
}
